   364      if(chunk.length > png_u32max) return SPNG_ECHUNK_SIZE;
   365
   366      ctx->cur_chunk_bytes_left = chunk.length;
   367
   368      ctx->cur_actual_crc = crc32(0, NULL, 0);
   369      ctx->cur_actual_crc = crc32(ctx->cur_actual_crc, chunk.type, 4);
   370
   371      memcpy(&ctx->current_chunk, &chunk, sizeof(struct spng_chunk));
